// A fresh id on EVERY call (21 Sep 2026). The first gate's sink answered every send
// with one fixed sid; messages is unique on (client_id, external_id), so only the gate's
// first outbound was ever stored, and every run after it raised invariant 4.
// Per call, not per execution: one execution can send several messages (a handoff
// note and an operator alert), and they must not collide with each other either.
const hex = n => Array.from({ length: n }, () => Math.floor(Math.random() * 16).toString(16)).join('');
const h = hex(32);
return [{ json: {
  sid: 'SM' + h,                                   // Twilio's shape: SM + 32 hex
  id: [h.slice(0, 8), h.slice(8, 12), '4' + h.slice(13, 16), '8' + h.slice(17, 20), h.slice(20, 32)].join('-'),  // Resend's: a UUID
  status: 'queued',
  note: 'deploy gate sink: nothing was sent',
} }];
